"""Gloam: a roguelike turn engine. The rules are in README.md."""

# ---- house rules for this dungeon (they are part of the specification, see README.md) ----
HERO_HP = 12
HERO_ATK = 3
POTION = 6
TRAP_DMG = 2
SIGHT = 6
COUNTER = False
REGEN = 0
FIXED_SPEED = False
# ------------------------------------------------------------------------------------------


STATS = {"r": (3, 1, 100), "g": (6, 2, 60), "s": (4, 2, 150)}  # hp, attack, speed
DIRS = {"U": (-1, 0), "D": (1, 0), "L": (0, -1), "R": (0, 1)}
ORDER = "UDLR"


class Monster:
    def __init__(self, ident, kind, y, x):
        self.id = ident
        self.kind = kind
        self.y = y
        self.x = x
        self.hp, self.atk, speed = STATS[kind]
        self.speed = 100 if FIXED_SPEED else speed
        self.energy = 0


class Game:
    def __init__(self, text):
        self.maps = text.split("\n---\n")
        self.level = 0
        self.hp = HERO_HP
        self.keys = 0
        self.potions = 0
        self.tick = 0
        self.state = "playing"
        self._enter(0)

    def _enter(self, index):
        self.level = index
        rows = self.maps[index].split("\n")
        self.h = len(rows)
        self.w = len(rows[0])
        self.grid = []
        self.monsters = []
        self.hero = [0, 0]
        for y, row in enumerate(rows):
            line = []
            for x, ch in enumerate(row):
                if ch == "@":
                    self.hero = [y, x]
                    ch = "."
                elif ch in STATS:
                    self.monsters.append(Monster("%s%d" % (ch, len(self.monsters) + 1), ch, y, x))
                    ch = "."
                line.append(ch)
            self.grid.append(line)

    def _cell(self, y, x):
        if y < 0 or x < 0 or y >= self.h or x >= self.w:
            return "#"
        return self.grid[y][x]

    def _monster_at(self, y, x):
        for m in self.monsters:
            if m.y == y and m.x == x:
                return m
        return None

    def legal_moves(self):
        if self.state != "playing":
            return []
        moves = []
        for name in ORDER:
            dy, dx = DIRS[name]
            cell = self._cell(self.hero[0] + dy, self.hero[1] + dx)
            if cell == "#" or (cell == "D" and self.keys == 0):
                continue
            moves.append(name)
        moves.append("wait")
        if self.potions > 0 and self.hp < HERO_HP:
            moves.append("drink")
        return moves

    def apply(self, move):
        if move not in self.legal_moves():
            raise ValueError("illegal move: %r" % (move,))
        events = []
        if move == "wait":
            events.append("hero waits")
        elif move == "drink":
            heal = min(POTION, HERO_HP - self.hp)
            self.potions -= 1
            self.hp += heal
            events.append("hero drinks +%d" % heal)
        else:
            self._hero_step(move, events)
